interface ResultHeroProps {
  directionName: string;
  directionDescription: string;
  message: string;
}

// Same copy discipline as the akinator reveal screen (RevealCard): the
// hedge lives in `message` (generated by akinator_report_service — "похоже",
// "может тебе подойти"), never a flat "твоя профессия — X" claim here.
export function ResultHero({ directionName, directionDescription, message }: ResultHeroProps) {
  return (
    <div
      className="relative overflow-hidden rounded-[24px] p-[30px_32px] text-on-brand"
      style={{ background: 'linear-gradient(135deg,#7C3AED,#6D28D9)', boxShadow: '0 14px 32px rgba(124,58,237,.26)' }}
    >
      <div
        className="absolute bottom-[-60px] right-[-30px] w-[220px] h-[220px] rounded-full pointer-events-none"
        style={{ background: 'rgba(255,255,255,0.08)' }}
      />
      <div className="relative flex flex-col gap-3">
        <span className="font-extrabold tracking-[.06em] uppercase opacity-85" style={{ fontSize: 13 }}>
          🎯 Похоже, тебе подходит
        </span>
        <h2 className="font-black tracking-[-0.01em] text-[32px] leading-tight">{directionName}</h2>
        <p className="font-semibold opacity-90 leading-relaxed text-base max-w-2xl">{message}</p>
        {directionDescription && (
          <p className="opacity-80 leading-relaxed text-[15px] max-w-2xl">{directionDescription}</p>
        )}
      </div>
    </div>
  );
}
